## Tic-Tac-Toe Deluxe

### The Board and Pieces

```xiom
enum Cell {
  Empty;
  X;
  O;
}

fn cell_char(c: Cell) -> Str {
  match c {
    Cell.Empty => ".",
    Cell.X => "X",
    Cell.O => "O",
  }
}

type Board {
  grid: Vec[Vec[Cell]];
}
```

### Creating and Displaying

```xiom
fn new_board() -> Board {
  let mut grid: Vec[Vec[Cell]] = Vec[Vec[Cell]].new();
  let mut r = 0;
  while r < 3 {
    let mut row: Vec[Cell] = Vec[Cell].new();
    let mut c = 0;
    while c < 3 {
      row.push(Cell.Empty);
      c += 1;
    };
    grid.push(row);
    r += 1;
  };
  Board{ grid: grid }
}

fn display_board(board: &Board) {
  let mut r = 0;
  while r < 3 {
    let mut line: Str = "";
    let mut c = 0;
    while c < 3 {
      let cell = board.grid.get(r).unwrap().get(c).unwrap();
      line = line + cell_char(cell) + " ";
      c += 1;
    };
    io.println(line);
    r += 1;
  };
}
```

### Making a Move

```xiom
fn make_move(board: &mut Board, row: Int, col: Int, player: Cell) -> Bool {
  let current = board.grid.get(row).unwrap().get(col).unwrap();
  if current != Cell.Empty { return false; };
  board.grid.get(row).unwrap().set(col, player);
  true
}
```

### Checking Win Conditions

```xiom
fn check_rows(board: &Board) -> Cell {
  let mut r = 0;
  while r < 3 {
    let a = board.grid.get(r).unwrap().get(0).unwrap();
    let b = board.grid.get(r).unwrap().get(1).unwrap();
    let c = board.grid.get(r).unwrap().get(2).unwrap();
    if a != Cell.Empty && a == b && b == c { return a; };
    r += 1;
  };
  Cell.Empty
}

fn check_cols(board: &Board) -> Cell {
  let mut c = 0;
  while c < 3 {
    let a = board.grid.get(0).unwrap().get(c).unwrap();
    let b = board.grid.get(1).unwrap().get(c).unwrap();
    let c2 = board.grid.get(2).unwrap().get(c).unwrap();
    if a != Cell.Empty && a == b && b == c2 { return a; };
    c += 1;
  };
  Cell.Empty
}

fn check_diags(board: &Board) -> Cell {
  let center = board.grid.get(1).unwrap().get(1).unwrap();
  if center == Cell.Empty { return Cell.Empty; };

  let tl = board.grid.get(0).unwrap().get(0).unwrap();
  let br = board.grid.get(2).unwrap().get(2).unwrap();
  if center == tl && tl == br { return center; };

  let tr = board.grid.get(0).unwrap().get(2).unwrap();
  let bl = board.grid.get(2).unwrap().get(0).unwrap();
  if center == tr && tr == bl { return center; };

  Cell.Empty
}
```

### Checking for Draw

```xiom
fn is_draw(board: &Board) -> Bool {
  let mut r = 0;
  while r < 3 {
    let mut c = 0;
    while c < 3 {
      let cell = board.grid.get(r).unwrap().get(c).unwrap();
      if cell == Cell.Empty { return false; };
      c += 1;
    };
    r += 1;
  };
  true
}

fn get_winner(board: &Board) -> Cell {
  let w = check_rows(board);
  if w != Cell.Empty { return w; };
  let w2 = check_cols(board);
  if w2 != Cell.Empty { return w2; };
  check_diags(board)
}
```

